\begin{align}
 H_{N,k,m}&\stackrel d=H_{N,m,k},\label{eq:sym1}\\
 H_{N,N-k,m}&\stackrel d=m-H_{N,k,m},\label{eq:sym2}\\
 H_{N,k,N-m}&\stackrel d=k-H_{N,k,m},\label{eq:sym3}\\
 H_{N,N-k,N-m}&\stackrel d=N-k-m+H_{N,k,m}.\label{eq:sym4}
\end{align}

\begin{equation}\label{eq:param}
 k=j,\qquad m=j+h,\qquad N=2j+h+r,
 \qquad j\ge1,\ h,r\in\mathbb Z_{\ge0}.
\end{equation}

\begin{equation}\label{eq:Q}
 Q_j(z)=\sum_{i=0}^j q_i z^i,
 \qquad
 q_i=\binom ji (j+h)_{\underline i}
 \frac{(r+j)!}{(r+i)!},
\end{equation}

\begin{equation}\label{B:disc}
\bar m(N-\bar m)-\bar k(N-\bar k)
=(\bar m-\bar k)(N-\bar m-\bar k)
\end{equation}

\begin{equation}\label{A:J}
 J(v)=
 \begin{cases}
 I_B(v)+I_P(r_-)-I_B(r_-)
 +(v-r_-)[I_P'(r_-)-I_B'(r_-)],&0\le v<r_-,\\
 I_P(v),&r_-\le v\le r_+,\\
 I_B(v)+I_P(r_+)-I_B(r_+)
 +(v-r_+)[I_P'(r_+)-I_B'(r_+)],&r_+<v\le m.
 \end{cases}
\end{equation}

\begin{align*}
 R_1(v)&=mD(v/m\Vert k/N),&
 R_2(v)&=kD(v/k\Vert m/N),\\
 R_3(v)&=(N-m)D((k-v)/(N-m)\Vert k/N),&
 R_4(v)&=(N-k)D((m-v)/(N-k)\Vert m/N).
\end{align*}

